## 6.  A unit‑style test (Junit 5)

```java
import org.junit.jupiter.api.*;

class ChainOfResponsibilityTest {

    private Handler<UserRegistration> chain;

    @BeforeEach
    void setUp() {
        chain = new NotEmptyValidator()
                .setNext(new PasswordLengthValidator(8))
                .setNext(new PersistUserHandler());
    }

    @Test
    void testSuccessPath() {
        var req = new UserRegistration("john", "john@example.com", "Password123");
        Assertions.assertTrue(chain.handle(req));
    }

    @Test
    void testEmptyUsername() {
        var req = new UserRegistration("", "john@example.com", "Password123");
        Assertions.assertFalse(chain.handle(req));
    }

    @Test
    void testShortPassword() {
        var req = new UserRegistration("john", "john@example.com", "short");
        Assertions.assertFalse(chain.handle(req));
    }
}
```

